import {esc,fmt,initials,normaliseBoard,wrapSpotlight} from './lib.js';
import {cinemaToolbar,openingMarkup,decorateStage,playerVault} from './cinema.js';
import {playerAvatar,portrait,portraitFor} from './photos.js';
import {mountSpotlightMotion} from './spotlight-motion.js';

const crown=`<svg viewBox="0 0 42 24" aria-hidden="true"><path d="m4 17-3-13 11 6L21 1l9 9 11-6-3 13Z" fill="currentColor"/><path d="M5 22h32" stroke="currentColor" stroke-width="2"/></svg>`;
const key=p=>`${p.role}:${p.id}`;
const names={bat:'BATTING',bowl:'BOWLING'};

export function createSelectionRoom(data,{onInspect,onCompare,notify,shouldReduceMotion}) {
  let role='bat',index=0,flipped=false,board=[],root,introPending=true,cinema=false,presentTimer=null,direction='next',cinemaReturnFocus,disposeCardMotion=()=>{};
  try{if(typeof window!=='undefined')board=normaliseBoard(JSON.parse(localStorage.getItem('rr-review-board')||'[]'),data.players);}catch{}
  const picks=()=>data.players.filter(p=>p.role===role&&p.rank<=10).sort((a,b)=>a.rank-b.rank);
  const find=k=>data.players.find(p=>key(p)===k);
  const save=()=>{try{localStorage.setItem('rr-review-board',JSON.stringify(board));}catch{notify('Board updated for this session; browser storage is unavailable.');}};
  function teaser(){return teaserCore().replace('<span class="teaser-initials">RS</span>',portrait({id:'7327'},{className:'teaser-player-photo'}));}
  function boardPortrait(p){return portraitFor(p)?portrait(p,{className:'board-portrait'}):`<span class="board-initials">${esc(initials(p.shortName))}</span>`;}
  function teaserCore(){return `<a href="#auction" class="room-teaser" aria-label="Enter the auction-inspired selection room"><div class="teaser-copy"><span class="eyebrow">TAKE YOUR SEAT AT THE TABLE</span><h2>The selection room.</h2><p>Twenty player cards. Every number on the table.<br>Turn the card. Inspect the evidence. Build your review board.</p><span class="teaser-cta">Enter the room <span>↗</span></span></div><div class="teaser-cards" aria-hidden="true"><div class="teaser-card card-back">${crown}<span>RR</span><small>PRESSURE LAB</small></div><div class="teaser-card card-front"><span class="teaser-rank">01 / BOWLING</span><span class="teaser-initials">RS</span><strong>RASIKH<br>SALAM</strong><div><b>63.93</b><small>INDEX POINTS</small></div></div><div class="teaser-card card-gold">${crown}<span>20</span><small>FINAL SELECTIONS</small></div></div><span class="teaser-orbit" aria-hidden="true"></span></a>`;}
  function ticker(){const text=['bat','bowl'].flatMap(r=>data.players.filter(p=>p.role===r&&p.rank<=10).sort((a,b)=>a.rank-b.rank).map(p=>`<span><i class="ticker-dot ${r}"></i>${esc(p.shortName)} <b>${fmt(p.score,2)}</b><small>${r==='bat'?'BAT':'BOWL'} #${p.rank}</small></span>`)).join('');return `<div class="ranking-ticker" aria-label="Final selections ticker"><div class="ticker-caption">THE FINAL<br><strong>TWENTY</strong></div><div class="ticker-window"><div class="ticker-track"><div>${text}</div><div aria-hidden="true">${text}</div></div></div></div>`;}
  function render(){introPending=true;return renderCore().replace('<div class="auction-room">',`<div class="auction-room">${cinemaToolbar()}`).replace('<section class="review-desk card"',`<section class="player-vault" aria-label="Player vault">${playerVault(data.players,role,index)}</section><section class="review-desk card"`);}
  function renderCore(){return `<div class="auction-room"><div class="room-intro"><div><div class="eyebrow">THE SELECTION ROOM</div><h1>Great players.<br><em>Greater scrutiny.</em></h1><p>An auction-room stage for the evidence. Explore the final twenty, flip each card and keep the players you want to discuss on your review board.</p></div><div class="room-seal">${crown}<span>HALLA BOL</span><small>ROUND 01 / RESEARCH</small></div></div><div class="room-disclosure"><span>AUCTION-INSPIRED DESIGN</span><p>Historical pressure rankings. No bids, prices or claims of auction availability.</p></div>${ticker()}<section id="auction-stage" aria-label="Player spotlight">${stage()}</section><section class="review-desk card" aria-labelledby="board-title">${desk()}</section><div class="room-bottom-note"><span>◈</span><p>The score remains the score. Saving a card changes only your personal review board—never the official rankings. Your board is stored in this browser.</p><a href="#robustness">Inspect the method ↗</a></div></div>`;}
  function stage(){const intro=introPending;introPending=false;return decorateStage(stageCore(),picks()[index],{intro,direction,flipped});}
  function stageCore(){
    const p=picks()[index],saved=board.includes(key(p));
    return `<div class="auction-stage ${role}"><div class="stage-grid" aria-hidden="true"></div><div class="stage-beam beam-one" aria-hidden="true"></div><div class="stage-beam beam-two" aria-hidden="true"></div><div class="stage-sparks" aria-hidden="true">${Array.from({length:9},(_,i)=>`<i style="--particle:${i}"></i>`).join('')}</div><div class="stage-top"><span class="stage-kicker"><i></i>PLAYER SPOTLIGHT <b>${String(index+1).padStart(2,'0')} / 10</b></span><div class="stage-role-switch" aria-label="Spotlight role"><button data-room-role="bat" aria-pressed="${role==='bat'}" class="${role==='bat'?'active':''}">Batters</button><button data-room-role="bowl" aria-pressed="${role==='bowl'}" class="${role==='bowl'?'active':''}">Bowlers</button></div></div><div class="stage-content"><div class="stage-copy"><div class="stage-overline">OFFICIAL ${names[role]} RANK <strong>#${String(p.rank).padStart(2,'0')}</strong></div><h2>${esc(p.shortName)}</h2><p class="stage-description">${p.wins} positive pressure appearances.<br>${p.n} opportunities to deliver.</p><div class="stage-metrics"><div><strong>${fmt(p.score,2)}</strong><span>RELIABILITY INDEX</span></div><div><strong>${fmt(p.exposure,0)}</strong><span>PRESSURE EXPOSURE</span></div></div><div class="stage-actions"><button class="button button-pink" data-board-toggle="${key(p)}" aria-pressed="${saved}"><span>${saved?'✓':'+'}</span> ${saved?'On your review board':'Add to review board'}</button><button class="stage-evidence" data-room-inspect="${key(p)}">Open full evidence ↗</button></div><p class="stage-fineprint">Index points, not win probability.<br>Pressure exposure follows each role’s delivery rules.</p></div><div class="card-stage"><div class="card-halo" aria-hidden="true"></div><div class="card-pedestal" aria-hidden="true"></div><div class="spotlight-card"><div class="player-flipper ${flipped?'is-flipped':''}"><div class="collectible front" aria-hidden="${flipped}"><div class="collectible-grain"></div><div class="collectible-top"><span>SUPERR<br><b>SELECTOR</b></span>${crown}</div><span class="collectible-rank">${String(p.rank).padStart(2,'0')}</span><div class="jersey-art" aria-hidden="true"><svg viewBox="0 0 250 230"><defs><linearGradient id="jersey-${role}" x1="0" x2="1" y2="1"><stop stop-color="${role==='bat'?'#ff79bc':'#83a5ff'}"/><stop offset="1" stop-color="${role==='bat'?'#c7257b':'#284bc1'}"/></linearGradient></defs><path d="m79 41-52 28-19 62 41 13 20-36-7 105h126l-7-105 20 36 41-13-19-62-52-28c-9 17-26 23-46 23s-37-6-46-23Z" fill="url(#jersey-${role})" stroke="#ffffff33"/><path d="m79 41 16 32 30 15 30-15 16-32" fill="#0b123d" stroke="#ffffff55"/><path d="M65 158h120M64 175h122" stroke="#ffffff14" stroke-width="9"/><path d="m29 77 33 18m126 0 33-18" stroke="#ffffff32" stroke-width="4"/><path d="M70 105h110" stroke="#ffffff18" stroke-width="2"/></svg><span>${esc(initials(p.shortName))}</span><small>PRESSURE LAB</small></div><div class="collectible-name"><span>${names[role]} · FINAL SELECTION</span><strong>${esc(p.shortName)}</strong></div><div class="collectible-footer"><div><b>${fmt(p.score,2)}</b><small>INDEX / 100</small></div><div><b>${p.wins}<i>/${p.n}</i></b><small>POSITIVE APPEARANCES</small></div></div></div><div class="collectible back" aria-hidden="${!flipped}"><div class="collectible-grain"></div><div class="collectible-top"><span>BEHIND<br><b>THE NUMBER</b></span>${crown}</div><h3>${esc(p.shortName)}</h3><p class="card-back-sub">The evidence, at a glance.</p><dl><div><dt>Pressure positives</dt><dd>${p.wins} / ${p.n}</dd></div><div><dt>Own-usual lift</dt><dd>${p.lift>=0?'+':''}${fmt(p.lift)} pp</dd></div><div><dt>Net utility / 100</dt><dd>${p.utility>=0?'+':''}${fmt(p.utility)}</dd></div><div><dt>Conditional rank interval</dt><dd>${fmt(p.rankLow,0)}–${fmt(p.rankHigh,0)}</dd></div></dl><p class="card-back-note">Whole-fixture bootstrap rank interval, 80%. Conditional on fixed models, labels and eligible cohort.</p><span class="card-back-stamp">EVIDENCE BEFORE INSTINCT</span></div></div></div><button class="flip-control" data-card-flip aria-pressed="${flipped}"><span>⇄</span> ${flipped?'Show player card':'Turn card for evidence'}</button></div></div><div class="stage-bottom"><button class="stage-nav" data-spotlight-step="-1" aria-label="Previous player">←</button><div class="spotlight-dots" aria-label="Select player">${picks().map((p,i)=>`<button data-spotlight-index="${i}" aria-label="${esc(p.shortName)}" aria-pressed="${i===index}" class="${i===index?'active':''}"></button>`).join('')}</div><button class="stage-nav" data-spotlight-step="1" aria-label="Next player">→</button><span class="stage-browse-label">BROWSE THE ${role==='bat'?'BATTERS':'BOWLERS'}</span></div></div>`;
  }
  function desk(){
    return `<div class="desk-head"><div><span class="eyebrow">YOUR PERSONAL RESEARCH DESK</span><h2 id="board-title">The review board <span>${board.length} / 20</span></h2><p>Keep evidence you want to revisit. This is your working board, separate from the final selections.</p></div>${board.length?'<button class="text-link" data-clear-board>Clear board ×</button>':''}</div>${board.length?`<div class="board-grid">${board.map(k=>{const p=find(k);return `<article class="board-card ${p.role}"><span class="board-role">${names[p.role]} #${p.rank}</span><button class="board-remove" data-board-toggle="${key(p)}" aria-label="Remove ${esc(p.shortName)} from review board">×</button>${boardPortrait(p)}<h3>${esc(p.shortName)}</h3><div class="board-card-score"><strong>${fmt(p.score,2)}</strong><span>INDEX<br>POINTS</span></div><div class="board-card-actions"><button data-room-inspect="${key(p)}">Evidence ↗</button><button data-room-compare="${key(p)}">Compare ⇄</button></div></article>`;}).join('')}</div>`:`<div class="board-empty"><span class="empty-card" aria-hidden="true">+</span><div><h3>Your next question starts with a player.</h3><p>Add a spotlight card to start your board. The final ten in each role stay fixed.</p></div><button class="button button-outline compact" data-add-current>Add current player +</button></div>`}`;
  }
  function mountCardMotion(){disposeCardMotion();disposeCardMotion=mountSpotlightMotion(root?.querySelector('.spotlight-card'),shouldReduceMotion);}
  function flipCard(){stopShowreel();flipped=!flipped;root.querySelector('.player-flipper').classList.toggle('is-flipped',flipped);root.querySelector('.collectible.front').setAttribute('aria-hidden',String(flipped));root.querySelector('.collectible.back').setAttribute('aria-hidden',String(!flipped));root.querySelectorAll('[data-card-flip]').forEach(control=>{control.setAttribute('aria-pressed',String(flipped));if(control.classList.contains('spotlight-card'))control.setAttribute('aria-label',`${picks()[index].shortName}: ${flipped?'show player portrait':'show player evidence'}`);else control.innerHTML=`<span>⇄</span> ${flipped?'Show player card':'Turn card for evidence'}`;});}
  function updateStage(){const el=root?.querySelector('#auction-stage');if(el){disposeCardMotion();el.innerHTML=stage();mountCardMotion();root.querySelectorAll('.spotlight-rail [data-spotlight-index]').forEach(button=>{const selected=Number(button.dataset.spotlightIndex)===index;button.classList.toggle('is-selected',selected);button.setAttribute('aria-pressed',String(selected));button.querySelector('.rail-selected-label').textContent=selected?'IN THE SPOTLIGHT':'VIEW PLAYER';button.querySelector('.rail-bottom i').textContent=selected?'↗':'+';});}}
  function updateVault(){const vault=root.querySelector('.player-vault');if(vault)vault.innerHTML=playerVault(data.players,role,index);}
  function syncCinemaControls(){const c=root?.querySelector('[data-cinema-toggle]'),s=root?.querySelector('[data-showreel-toggle]'),m=root?.querySelector('[data-cinema-motion]');if(c){c.setAttribute('aria-pressed',String(cinema));c.innerHTML=`${cinema?'⊡':'⛶'} <span>${cinema?'Exit cinema':'Cinema view'}</span>`;}if(s){s.setAttribute('aria-pressed',String(!!presentTimer));s.innerHTML=`${presentTimer?'Ⅱ':'▷'} <span>${presentTimer?'Pause showreel':'Play showreel'}</span>`;}if(m){const reduced=shouldReduceMotion();m.setAttribute('aria-pressed',String(reduced));m.innerHTML=`${reduced?'○':'◉'} <span>${reduced?'Effects off':'Effects on'}</span>`;m.disabled=!!document.querySelector('#motion-toggle')?.disabled;m.setAttribute('aria-label',reduced?'Play decorative effects':'Pause decorative effects');m.title=m.disabled?'Reduced motion follows your device setting':m.getAttribute('aria-label');}}
  function stopShowreel(){if(presentTimer)clearInterval(presentTimer);presentTimer=null;syncCinemaControls();}
  function toggleShowreel(){if(presentTimer){stopShowreel();return;}if(shouldReduceMotion()){notify('Enable animations to play the showreel. Manual player browsing remains available.');return;}presentTimer=setInterval(()=>{if(document.hidden||shouldReduceMotion()||document.querySelector('dialog[open]')||root.querySelector('#auction-stage')?.contains(document.activeElement))return;direction='next';index=wrapSpotlight(index,1,picks().length);flipped=false;updateStage();},7500);syncCinemaControls();notify('Showreel playing: advances every 7.5 seconds.');}
  function toggleCinema(force){cinema=typeof force==='boolean'?force:!cinema;document.body.classList.toggle('cinema-mode',cinema);syncCinemaControls();if(cinema){cinemaReturnFocus=document.activeElement;root.querySelector('[data-cinema-toggle]')?.focus({preventScroll:true});root.scrollIntoView({behavior:'instant',block:'start'});}else{stopShowreel();if(cinemaReturnFocus?.isConnected)cinemaReturnFocus.focus({preventScroll:true});}}
  function onRoomKey(e){if(document.querySelector('dialog[open]')||e.target.closest('input,select,textarea,[contenteditable=true]')||e.altKey||e.metaKey||e.ctrlKey)return;if(e.target.closest('.spotlight-card')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();if(!e.repeat)flipCard();}else if(e.key==='Escape'&&cinema){e.preventDefault();toggleCinema(false);}else if(cinema&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){e.preventDefault();stopShowreel();const step=e.key==='ArrowRight'?1:-1;direction=step>0?'next':'previous';index=wrapSpotlight(index,step,picks().length);flipped=false;updateStage();root.querySelector(`[data-spotlight-step="${step}"]`)?.focus({preventScroll:true});}}
  function onMotionChange(){if(shouldReduceMotion())stopShowreel();mountCardMotion();syncCinemaControls();}
  function cleanup(){stopShowreel();disposeCardMotion();disposeCardMotion=()=>{};document.body.classList.remove('cinema-mode');cinema=false;document.removeEventListener('keydown',onRoomKey);document.removeEventListener('rr-motion-change',onMotionChange);root=null;}
  function updateBoard(){root.querySelector('.review-desk').innerHTML=desk();}
  function toggleBoard(k,button){
    if(!find(k)||find(k).rank>10)return;
    const exists=board.includes(k);board=normaliseBoard(exists?board.filter(x=>x!==k):[...board,k],data.players);save();updateBoard();
    const currentKey=key(picks()[index]);const stageButton=root.querySelector('.stage-actions [data-board-toggle]');
    if(stageButton&&currentKey===k){const isSaved=board.includes(k);stageButton.setAttribute('aria-pressed',String(isSaved));stageButton.innerHTML=`<span>${isSaved?'✓':'+'}</span> ${isSaved?'On your review board':'Add to review board'}`;}
    notify(exists?'Removed from your review board':'Added to your review board');
    if(!exists&&!shouldReduceMotion()&&button?.isConnected){const burst=document.createElement('span');burst.className='card-spark-burst';burst.setAttribute('aria-hidden','true');burst.innerHTML=Array.from({length:8},(_,i)=>`<i style="--spark:${i}"></i>`).join('');button.append(burst);setTimeout(()=>burst.remove(),850);}
  }
  function bind(){root=document.querySelector('.auction-room');if(!root)return;mountCardMotion();syncCinemaControls();document.addEventListener('keydown',onRoomKey);document.addEventListener('rr-motion-change',onMotionChange);root.addEventListener('click',e=>{
    const target=e.target.closest('button,[data-card-flip]');if(!target)return;
    if(target.hasAttribute('data-cinema-toggle')){toggleCinema();}
    else if(target.hasAttribute('data-cinema-motion')){document.querySelector('#motion-toggle')?.click();}
    else if(target.hasAttribute('data-showreel-toggle')){toggleShowreel();}
    else if(target.hasAttribute('data-replay-entrance')){if(shouldReduceMotion()){notify('The entrance is hidden while decorative effects are paused.');return;}root.querySelector('.cinema-opening')?.remove();root.querySelector('.auction-stage').insertAdjacentHTML('beforeend',openingMarkup());notify('Replaying the stage entrance.');}
    else if(target.dataset.roomRole){stopShowreel();role=target.dataset.roomRole;index=0;flipped=false;direction='next';updateVault();updateStage();root.querySelector(`[data-room-role="${role}"]`)?.focus({preventScroll:true});}
    else if(target.dataset.spotlightStep){stopShowreel();const step=Number(target.dataset.spotlightStep);direction=step>0?'next':'previous';index=wrapSpotlight(index,step,picks().length);flipped=false;updateStage();root.querySelector(`[data-spotlight-step="${step}"]`)?.focus({preventScroll:true});}
    else if(target.dataset.spotlightIndex!==undefined){stopShowreel();const fromRail=target.classList.contains('rail-card'),nextIndex=Number(target.dataset.spotlightIndex);direction=nextIndex<index?'previous':'next';index=nextIndex;flipped=false;updateStage();root.querySelector(`${fromRail?'.spotlight-rail ':'.spotlight-dots '}[data-spotlight-index="${index}"]`)?.focus({preventScroll:true});}
    else if(target.hasAttribute('data-card-flip')){flipCard();}
    else if(target.dataset.boardToggle){const k=target.dataset.boardToggle,isRemoval=target.classList.contains('board-remove');toggleBoard(k,target);if(isRemoval)root.querySelector('.review-desk button')?.focus();}
    else if(target.hasAttribute('data-add-current')){toggleBoard(key(picks()[index]),target);root.querySelector('.review-desk button')?.focus();}
    else if(target.hasAttribute('data-clear-board')){board=[];save();updateBoard();updateStage();root.querySelector('[data-add-current]')?.focus();notify('Review board cleared. Official rankings are unchanged.');}
    else if(target.dataset.roomInspect)onInspect(target.dataset.roomInspect);
    else if(target.dataset.roomCompare)onCompare(target.dataset.roomCompare);
  });}
  return {teaser,render,bind,cleanup};
}
